/* Editorial selections reference, but never modify, the full catalogue. */
(() => {
  const q=s=>document.querySelector(s);
  const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const data=()=>window.STEM_DATA.top_picks;
  const selection={category:'',kid:'',horizon:'now',query:''};
  const fitNames={candidate:"edad / candidato escolar",confirm:"el permiso para especificar",future:"más tarde",no:"edad cerrada"};
  const tierNames={main:"la elección principal",alternative:"la alternativa para la tarea"};
  function matching(p){return (!selection.category||p.category===selection.category)&&(!selection.horizon||p.horizon===selection.horizon)&&(!selection.kid||(selection.kid==='both'?p.fit.mat==='candidate'&&p.fit.osc==='candidate':p.fit[selection.kid]!=='no'))&&(!selection.query||JSON.stringify(p).toLocaleLowerCase('es').includes(selection.query.toLocaleLowerCase('es')))}
  function card(p){
    const school=p.category==='school',league=p.category==='league';
    const actions=p.target_ids.map(id=>school?`<button class="button secondary" data-school-open="${safe(id)}">archivo escolar</button>`:league?`<button class="button secondary" data-best-league="${safe(id)}">reglas y ruta</button>`:`<button class="button secondary" data-open="${safe(id)}">${p.target_ids.length>1?safe(window.STEM_DATA.events.find(e=>e.id===id)?.title.replace(/^.*? · /,'')):"Dossier completo"} ↗</button>`).join('');
    return `<article class="best-card ${safe(p.category)} ${safe(p.tier)}" id="best-${safe(p.id)}" data-pick-id="${safe(p.id)}" tabindex="-1"><div class="best-card-heading"><span>${safe(data().categories[p.category])} · ${safe(p.place)}</span><span class="best-star" aria-hidden="true">✦</span></div><div class="best-card-body"><div class="best-tags"><span>${p.horizon==='future'?"el futuro de la ruta":safe(tierNames[p.tier])}</span><span>${p.horizon==='future'?"edad más tarde":"la etapa para considerar ahora"}</span></div><h3>${safe(p.title)}</h3><p class="best-promise">${safe(p.label)}</p><p>${safe(p.why)}</p><div class="best-fit">${['mat','osc'].map(k=>`<span class="${safe(p.fit[k])}">${k==='mat'?"Matvey":"Oscar"} · ${safe(fitNames[p.fit[k]])}</span>`).join('')}</div><div class="best-facts"><strong>que se confirmó</strong><p>${safe(p.facts)}</p></div><div class="best-gate"><strong>¿Qué decidir antes de elegir?</strong><p>${safe(p.gate)}</p></div><details class="best-details"><summary>el siguiente paso y las fuentes primarias</summary><p>${safe(p.next_action)}</p>${p.sources.map(s=>`<a href="${safe(s.url)}" target="_blank" rel="noopener">${safe(s.title)} ↗</a>`).join('')}<small>Se ha convertido 01.10.2026 · La calidad de la clase no ha sido comprobada personalmente.</small></details><div class="best-card-actions">${actions}</div></div></article>`;
  }
  function render(){
    const d=data(),root=q('#best-content');if(!d||!root)return;
    if(!root.dataset.ready){root.innerHTML=`<div class="best-hero"><div><p class="best-eyebrow">✦ SELECCIÓN FAMILIAR · 6 Y 9 AÑOS</p><h3>Es un equipo fuerte.<br><em>Es un proyecto propio.</em></h3><p>${safe(d.recommendation)}</p><a class="text-button" href="downloads/STEM_top_picks.md" download>descargar la selección con la fuente ↓</a></div><div class="best-orbit" aria-hidden="true"><span class="orbit-ring one"></span><span class="orbit-ring two"></span><span class="orbit-ring three"></span><span class="orbit-core">✦</span><span class="orbit-point p1">escuela</span><span class="orbit-point p2">Equipo</span><span class="orbit-point p3">proyecto</span></div></div><p class="best-basis">${safe(d.basis)}</p><div class="best-category-tabs" role="group" aria-label="sección de selección"><button data-best-category="">Todos ${d.picks.length}</button>${Object.entries(d.categories).map(([k,v])=>`<button data-best-category="${k}">${safe(v)} <small>${d.picks.filter(p=>p.category===k).length}</small></button>`).join('')}</div><div class="best-controls"><label>el horizonte<select data-best-filter="horizon"><option value="now">Ahora se puede ver el conjunto por separado</option><option value="future">futuras etapas de edad</option><option value="">Ahora y el futuro</option></select></label><label>para quién<select data-best-filter="kid"><option value="">las dos rutas</option><option value="mat">Matvey · candidatos / más tarde</option><option value="osc">Oscar · candidatos / más tarde</option><option value="both">ambos candidatos de edad / escolar</option></select></label><label>encontrar en la selección<input data-best-filter="query" type="search" placeholder="Taiwan, el hogar, y..."></label><button class="text-button" data-best-reset>Restablecer</button></div><p id="best-count" class="best-count" aria-live="polite"></p><div id="best-cards" class="best-grid"></div><details class="best-method"><summary>¿Por qué estas opciones y dónde los límites de la elección</summary><ul>${d.methodology.map(t=>`<li>${safe(t)}</li>`).join('')}</ul><p>la prioridad no es igual a la solicitud aceptada, al cambio abierto o a la garantía de la medalla. el presupuesto se compara en el expediente completo. la etapa inicial diaria y la pensión de los mayores se evalúan por separado.</p><a href="downloads/STEM_top_picks.json" download>selección de datos · JSON ↓</a></details>`;root.dataset.ready='true'}
    root.querySelectorAll('[data-best-filter]').forEach(el=>{if(el.value!==selection[el.dataset.bestFilter])el.value=selection[el.dataset.bestFilter]});
    root.querySelectorAll('[data-best-category]').forEach(el=>{const on=el.dataset.bestCategory===selection.category;el.classList.toggle('active',on);el.setAttribute('aria-pressed',String(on))});
    const a=d.picks.filter(matching);q('#best-count').textContent=`${a.length} de ${d.picks.length} Las recomendaciones · current describe la etapa, no el lugar confirmado.`;
    q('#best-cards').innerHTML=a.length?a.map(card).join(''):"<div class=\"best-empty\"><h3>No hay coincidencias en esta selección.</h3><p>Si quieres, prueba otro horizonte o un niño.</p><button class=\"button secondary\" data-best-reset>mostrar todas las recomendaciones</button></div>";
  }
  window.renderBest=render;
  window.bestPickFor=(category,id)=>data()?.picks.find(p=>p.category===category&&p.target_ids.includes(id));
  window.bestEventPick=id=>data()?.picks.find(p=>(['camp','expo'].includes(p.category)&&p.target_ids.includes(id))||(p.event_ids||[]).includes(id));
  window.bestBadge=(category,id)=>{const p=category==='event'?window.bestEventPick(id):window.bestPickFor(category,id);return p?`<button class="best-badge" data-best-pick="${safe(p.id)}" title="${safe(p.label)}">✦ ${p.horizon==='future'?"nuestra elección · más tarde":"nuestra elección"} ↗</button>`:''};
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.hasAttribute('data-best-category')){selection.category=b.dataset.bestCategory;render()}
    if(b.hasAttribute('data-best-reset')){Object.assign(selection,{category:'',kid:'',horizon:'',query:''});render()}
    if(b.dataset.bestPick){Object.assign(selection,{category:'',kid:'',horizon:'',query:''});setView('best');const el=q('#best-'+b.dataset.bestPick);el?.scrollIntoView({behavior:'smooth',block:'start'});el?.focus({preventScroll:true})}
    if(b.dataset.bestLeague){setView('leagues');Object.assign(leagueState,{tab:'guide',query:'',group:'',age:'',best:false});leagueState.opened.add(b.dataset.bestLeague);renderLeagueGuide();const el=q('#league-'+b.dataset.bestLeague);el?.scrollIntoView({behavior:'smooth',block:'start'});el?.querySelector('summary')?.focus({preventScroll:true})}
  });
  document.addEventListener('change',e=>{const k=e.target.dataset.bestFilter;if(k&&k!=='query'){selection[k]=e.target.value;render()}});
  document.addEventListener('input',e=>{if(e.target.dataset.bestFilter==='query'){selection.query=e.target.value;render()}});
})();
